def sum_even(nums: list[int]) -> int:
    total = 0
    for x in nums:
        if x % 2 == 0:
            total += x
    return total

def is_clean_palindrome(text: str) -> bool:
    left = 0
    right = len(text) - 1
    while left < right:
        while left < right and not text[left].isalnum():
            left += 1
        while left < right and not text[right].isalnum():
            right -= 1
        if left < right:
            if text[left].lower() != text[right].lower():
                return False
            left += 1
            right -= 1
    return True

def two_sum(nums: list[int], target: int) -> list[int]:
    seen = {}
    for i, x in enumerate(nums):
        comp = target - x
        if comp in seen:
            return [seen[comp], i]
        seen[x] = i
    return []

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = []
    cur_start, cur_end = sorted_intervals[0]
    for interval in sorted_intervals[1:]:
        s, e = interval
        if s <= cur_end:
            cur_end = max(cur_end, e)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = s, e
    merged.append([cur_start, cur_end])
    return merged

def first_occurrence(nums: list[int], target: int) -> int:
    lo = 0
    hi = len(nums) - 1
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            ans = mid
            hi = mid - 1
        elif nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

def longest_unique_length(s: str) -> int:
    last = {}
    left = 0
    max_len = 0
    for right, ch in enumerate(s):
        if ch in last and last[ch] >= left:
            left = last[ch] + 1
        last[ch] = right
        cur = right - left + 1
        if cur > max_len:
            max_len = cur
    return max_len

def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)
    dp = list(range(n + 1))
    for i in range(1, m + 1):
        prev = dp[0]
        dp[0] = i
        for j in range(1, n + 1):
            temp = dp[j]
            if a[i-1] == b[j-1]:
                dp[j] = prev
            else:
                dp[j] = 1 + min(dp[j], dp[j-1], prev)
            prev = temp
    return dp[n]

def min_cover(s: str, t: str) -> str:
    if not t:
        return ""
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1
    total = len(need)
    have = {}
    satisfied = 0
    l = 0
    min_len = len(s) + 1
    min_start = 0
    for r in range(len(s)):
        c = s[r]
        if c in need:
            have[c] = have.get(c, 0) + 1
            if have[c] == need[c]:
                satisfied += 1
        while satisfied == total:
            cur_len = r - l + 1
            if cur_len < min_len:
                min_len = cur_len
                min_start = l
            c_l = s[l]
            if c_l in need:
                have[c_l] -= 1
                if have[c_l] < need[c_l]:
                    satisfied -= 1
            l += 1
    if min_len <= len(s):
        return s[min_start:min_start+min_len]
    return ""

def count_in_range(nums: list[int], lo: int, hi: int) -> int:
    cnt = 0
    for x in nums:
        if lo <= x <= hi:
            cnt += 1
    return cnt

def has_two_sum_sorted(nums: list[int], target: int) -> bool:
    n = len(nums)
    if n < 2:
        return False
    left = 0
    right = n - 1
    while left < right:
        s = nums[left] + nums[right]
        if s == target:
            return True
        elif s < target:
            left += 1
        else:
            right -= 1
    return False

def is_anagram(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    count = {}
    for ch in s:
        if ch in count:
            count[ch] += 1
        else:
            count[ch] = 1
    for ch in t:
        if ch not in count or count[ch] == 0:
            return False
        count[ch] -= 1
    for v in count.values():
        if v != 0:
            return False
    return True

def range_sums(nums: list[int], queries: list[tuple[int, int]]) -> list[int]:
    n = len(nums)
    if n == 0 or len(queries) == 0:
        return []
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i+1] = pref[i] + nums[i]
    res = []
    for l, r in queries:
        res.append(pref[r+1] - pref[l])
    return res

def normalize_spaces(text: str) -> str:
    words = []
    current = []
    for ch in text:
        if ch == ' ' or ch == '\t' or ch == '\n':
            if current:
                words.append(''.join(current))
                current = []
        else:
            current.append(ch)
    if current:
        words.append(''.join(current))
    return ' '.join(words)

def atm_balance(ops):
    balance = 0
    for op in ops:
        if op > 0:
            balance += op
        elif op < 0:
            if -op <= balance:
                balance += op
    return balance

def is_balanced(s: str) -> bool:
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in mapping.values():
            stack.append(c)
        else:
            if not stack or stack.pop() != mapping[c]:
                return False
    return len(stack) == 0

def trailing_zeros(n: int) -> int:
    cnt = 0
    while n >= 5:
        n //= 5
        cnt += n
    return cnt

def rotate_right(nums: list[int], k: int) -> list[int]:
    n = len(nums)
    if n == 0:
        return []
    k = k % n
    return nums[n-k:] + nums[:n-k]

def lower_bound(nums: list[int], target: int) -> int:
    left = 0
    right = len(nums)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid
    if left == len(nums):
        return -1
    return left

def max_adjacent_gap(nums: list[int]) -> int:
    if len(nums) < 2:
        return 0
    s = sorted(nums)
    max_gap = 0
    for i in range(1, len(s)):
        gap = s[i] - s[i-1]
        if gap > max_gap:
            max_gap = gap
    return max_gap

def count_distinct(nums: list[int]) -> int:
    seen = set()
    for x in nums:
        seen.add(x)
    return len(seen)

def single_number(nums):
    if not nums:
        return None
    res = 0
    for x in nums:
        res ^= x
    return res

def reverse_vowels(s: str) -> str:
    vowels = set('aeiouAEIOU')
    lst = list(s)
    l, r = 0, len(lst) - 1
    while l < r:
        while l < r and lst[l] not in vowels:
            l += 1
        while l < r and lst[r] not in vowels:
            r -= 1
        if l < r:
            lst[l], lst[r] = lst[r], lst[l]
            l += 1
            r -= 1
    return ''.join(lst)

def is_symmetric(matrix):
    n = len(matrix)
    if n == 0:
        return True
    for row in matrix:
        if len(row) != n:
            return False
    for i in range(n):
        for j in range(n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True

def count_positive_multiples(nums: list[int], k: int) -> int:
    cnt = 0
    for x in nums:
        if x > 0 and x % k == 0:
            cnt += 1
    return cnt

def inverse_permutation(perm):
    n = len(perm)
    if n == 0:
        return []
    inv = [0] * n
    for i, val in enumerate(perm):
        inv[val] = i
    return inv

def count_records(nums: list[int]) -> int:
    if not nums:
        return 0
    count = 0
    max_so_far = None
    for x in nums:
        if max_so_far is None:
            count += 1
            max_so_far = x
        elif x > max_so_far:
            count += 1
            max_so_far = x
    return count

def count_in_range(nums: list[int], low: int, high: int) -> int:
    if low > high or len(nums) == 0:
        return 0
    cnt = 0
    for x in nums:
        if low <= x <= high:
            cnt += 1
    return cnt

def char_freq(s: str) -> dict[str, int]:
    d = {}
    for c in s:
        if c in d:
            d[c] += 1
        else:
            d[c] = 1
    return d

def rotate_right(nums: list[int], k: int) -> list[int]:
    n = len(nums)
    if n == 0:
        return []
    k = k % n
    return nums[n-k:] + nums[:n-k]

def count_digit(n: int, d: int) -> int:
    s = str(abs(n))
    cnt = 0
    for ch in s:
        if int(ch) == d:
            cnt += 1
    return cnt

def common_sorted(a: list[int], b: list[int]) -> list[int]:
    if not a or not b:
        return []
    return sorted(set(a) & set(b))

def max_subarray_sum(nums: list[int]) -> int:
    if not nums:
        return 0
    max_end = nums[0]
    max_so_far = nums[0]
    for i in range(1, len(nums)):
        max_end = max(nums[i], max_end + nums[i])
        max_so_far = max(max_so_far, max_end)
    return max_so_far

def sort_by_frequency(nums):
    if len(nums) == 0:
        return []
    freq = {}
    for x in nums:
        if x in freq:
            freq[x] += 1
        else:
            freq[x] = 1
    keys = list(freq.keys())
    def get_key(x):
        return (-freq[x], x)
    return sorted(keys, key=get_key)

def length_of_longest_substring(s: str) -> int:
    last = {}
    max_len = 0
    left = 0
    for right, ch in enumerate(s):
        if ch in last and last[ch] >= left:
            left = last[ch] + 1
        last[ch] = right
        curr_len = right - left + 1
        if curr_len > max_len:
            max_len = curr_len
    return max_len

def first_ge(nums: list[int], target: int) -> int:
    lo = 0
    hi = len(nums)
    while lo < hi:
        mid = divmod(lo + hi, 2)[0]
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    if lo < len(nums):
        return lo
    return -1

def count_pairs_in_range(nums, low, high):
    freq = {}
    for x in nums:
        if x in freq:
            freq[x] += 1
        else:
            freq[x] = 1
    vals = sorted(freq.keys())
    k = len(vals)
    ans = 0
    for i in range(k):
        vi = vals[i]
        fi = freq[vi]
        for j in range(i, k):
            vj = vals[j]
            s = vi + vj
            if low <= s <= high:
                if i == j:
                    ans += fi * (fi - 1) // 2
                else:
                    ans += fi * freq[vj]
    return ans

def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals)
    merged = []
    for interval in sorted_intervals:
        if not merged:
            merged.append([interval[0], interval[1]])
        else:
            last = merged[-1]
            if interval[0] <= last[1]:
                last[1] = max(last[1], interval[1])
            else:
                merged.append([interval[0], interval[1]])
    return merged

def max_area(heights: list[int]) -> int:
    if len(heights) < 2:
        return 0
    l = 0
    r = len(heights) - 1
    max_a = 0
    while l < r:
        w = r - l
        h = min(heights[l], heights[r])
        a = w * h
        if a > max_a:
            max_a = a
        if heights[l] <= heights[r]:
            l += 1
        else:
            r -= 1
    return max_a

def count_subarray_sum(nums: list[int], k: int) -> int:
    count_map = {}
    count_map[0] = 1
    cur = 0
    ans = 0
    for num in nums:
        cur += num
        target = cur - k
        if target in count_map:
            ans += count_map[target]
        if cur in count_map:
            count_map[cur] += 1
        else:
            count_map[cur] = 1
    return ans

def daily_warmer(temps):
    n = len(temps)
    ans = [0] * n
    stack = []
    for i in range(n):
        while stack and temps[i] > temps[stack[-1]]:
            idx = stack.pop()
            ans[idx] = i - idx
        stack.append(i)
    return ans

def fast_power(x: float, n: int) -> float:
    if n == 0:
        return 1.0
    if n < 0:
        return 1.0 / fast_power(x, -n)
    half = fast_power(x, n // 2)
    if n % 2 == 0:
        return half * half
    else:
        return x * half * half

def spiral_order(matrix):
    if not matrix or not matrix[0]:
        return []
    res = []
    top = 0
    bottom = len(matrix) - 1
    left = 0
    right = len(matrix[0]) - 1
    while top <= bottom and left <= right:
        for i in range(left, right + 1):
            res.append(matrix[top][i])
        for i in range(top + 1, bottom + 1):
            res.append(matrix[i][right])
        if top < bottom:
            for i in range(right - 1, left - 1, -1):
                res.append(matrix[bottom][i])
        if left < right:
            for i in range(bottom - 1, top, -1):
                res.append(matrix[i][left])
        top += 1
        bottom -= 1
        left += 1
        right -= 1
    return res

def jump_count(nums: list[int]) -> int:
    n = len(nums)
    if n <= 1:
        return 0
    jumps = 0
    cur_end = 0
    farthest = 0
    for i in range(n - 1):
        farthest = max(farthest, i + nums[i])
        if i == cur_end:
            jumps += 1
            cur_end = farthest
            if cur_end >= n - 1:
                break
    return jumps

def top_scores(scores: list[int], k: int) -> list[int]:
    if k == 0 or len(scores) == 0:
        return []
    cnt = {}
    for s in scores:
        if s in cnt:
            cnt[s] += 1
        else:
            cnt[s] = 1
    items = [(cnt[s], s) for s in cnt]
    items = sorted(items, reverse=True)
    res = []
    for i in range(k if k < len(items) else len(items)):
        res.append(items[i][1])
    return res

def str_str(haystack: str, needle: str) -> int:
    if not needle:
        return 0
    n = len(needle)
    lps = [0] * n
    length = 0
    i = 1
    while i < n:
        if needle[i] == needle[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length != 0:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    m = len(haystack)
    i = 0
    j = 0
    while i < m:
        if haystack[i] == needle[j]:
            i += 1
            j += 1
            if j == n:
                return i - j
        elif j != 0:
            j = lps[j - 1]
        else:
            i += 1
    return -1

def max_sliding(nums: list[int], k: int) -> list[int]:
    if not nums or k <= 0 or k > len(nums):
        return []
    q = []
    head = 0
    res = []
    for i, x in enumerate(nums):
        if q and q[head] <= i - k:
            head += 1
        while q and nums[q[-1]] <= x:
            q.pop()
            if not q:
                head = 0
        q.append(i)
        if i >= k - 1:
            res.append(nums[q[head]])
    return res

def search_rotated(nums: list[int], target: int) -> int:
    n = len(nums)
    if n == 0:
        return -1
    left = 0
    right = n - 1
    while left <= right:
        mid = left + (right - left) // 2
        if nums[mid] == target:
            return mid
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1

def is_valid_stack_sequence(pushed, popped):
    if len(pushed) != len(popped):
        return False
    stack = []
    j = 0
    for x in pushed:
        stack.append(x)
        while stack and j < len(popped) and stack[-1] == popped[j]:
            stack.pop()
            j += 1
    return len(stack) == 0
